import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry bn2d_fwd(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 rm_ptr,
    .param .u64 rv_ptr,
    .param .u64 nbt_ptr,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W,
    .param .u32 training,
    .param .f32 momentum,
    .param .f32 eps
)
{
    // Shared memory for reductions and broadcasting mean/inv_std
    .shared .align 4 .f32 s_sum[256];
    .shared .align 4 .f32 s_sumsq[256];
    .shared .align 4 .f32 s_broadcast[2]; // [0]: mean, [1]: inv_std
    // Registers
    .reg .pred p_train, p_cond, p_loop, p_red, p_is_t0, p_is_b0, p_oob_c;
    .reg .u32 rN, rC, rH, rW, rHW, rM;
    .reg .u32 r_tid, r_ntid, r_bx;
    .reg .u32 r_idx, r_stride, r_n, r_hw, r_tmp32;
    .reg .u32 r_training;
    .reg .u64 rd_x, rd_y, rd_w, rd_b, rd_rm, rd_rv, rd_nbt;
    .reg .u64 rd_xg, rd_yg, rd_wg, rd_bg, rd_rmg, rd_rvg, rd_nbtg;
     .reg .u64 rd_off_bytes, rd_elem_off, rd_tmp64, rd_c4, rd_c64, rd_M64, rd_HW64, rd_C64, rd_n64, rd_nC64, rd_nC_HW64, rd_c_HW64, rd_hw64, rd_s_sum_base, rd_s_sumsq_base;
    .reg .f32 f_momentum, f_eps, f_sum, f_sumsq, f_one, f_zero;
    .reg .f32 f_mean, f_var, f_e2, f_std, f_invstd, f_M, f_x, f_y, f_w, f_b;
    .reg .f32 f_tmp1, f_tmp2, f_omn; // one_minus_m
    .reg .f32 f_rm_old, f_rv_old, f_rm_new, f_rv_new;
    // Load params
    ld.param.u64 rd_x,   [x_ptr];
    ld.param.u64 rd_y,   [y_ptr];
    ld.param.u64 rd_w,   [w_ptr];
    ld.param.u64 rd_b,   [b_ptr];
    ld.param.u64 rd_rm,  [rm_ptr];
    ld.param.u64 rd_rv,  [rv_ptr];
    ld.param.u64 rd_nbt, [nbt_ptr];
    ld.param.u32 rN,     [N];
    ld.param.u32 rC,     [C];
    ld.param.u32 rH,     [H];
    ld.param.u32 rW,     [W];
    ld.param.u32 r_training, [training];
    ld.param.f32 f_momentum, [momentum];
    ld.param.f32 f_eps, [eps];
    // Convert to global addresses
    cvta.to.global.u64 rd_xg,   rd_x;
    cvta.to.global.u64 rd_yg,   rd_y;
    cvta.to.global.u64 rd_wg,   rd_w;
    cvta.to.global.u64 rd_bg,   rd_b;
    cvta.to.global.u64 rd_rmg,  rd_rm;
    cvta.to.global.u64 rd_rvg,  rd_rv;
    cvta.to.global.u64 rd_nbtg, rd_nbt;
    // Thread/block indices
    mov.u32 r_tid, %tid.x;
    mov.u32 r_ntid, %ntid.x;
    mov.u32 r_bx, %ctaid.x;
    // Bounds check for channel
    setp.ge.u32 p_oob_c, r_bx, rC;
    @p_oob_c ret;
    // Precompute sizes
    mul.lo.u32 rHW, rH, rW;        // H*W
    mul.lo.u32 rM,  rN, rHW;       // N*H*W
    // Constants
    mov.f32 f_one, 1.0;
    mov.f32 f_zero, 0.0;
    // training predicate
    setp.ne.u32 p_train, r_training, 0;
    // Compute byte offset for this channel in 1D arrays (float32 => *4)
    // rd_c4 = r_bx * 4
    mul.wide.u32 rd_c4, r_bx, 4;
    // Load gamma and beta for this channel into registers
    {
        .reg .u64 rd_tmp;
        add.u64 rd_tmp, rd_wg, rd_c4;
        ld.global.f32 f_w, [rd_tmp];
        add.u64 rd_tmp, rd_bg, rd_c4;
        ld.global.f32 f_b, [rd_tmp];
    }
    // TRAINING path: compute mean/var, update running stats, broadcast mean/invstd
    @p_train bra TRAIN_PATH;
    // EVAL path
EVAL_PATH:
    // Thread 0 loads running mean/var for this channel, computes inv_std, stores to s_broadcast
    setp.eq.u32 p_is_t0, r_tid, 0;
    @!p_is_t0 bra EVAL_BCAST_SYNC;
    {
        .reg .u64 rd_tmp;
        add.u64 rd_tmp, rd_rmg, rd_c4;
        ld.global.f32 f_mean, [rd_tmp];
        add.u64 rd_tmp, rd_rvg, rd_c4;
        ld.global.f32 f_var, [rd_tmp];
        add.f32 f_var, f_var, f_eps;
        sqrt.rn.f32 f_std, f_var;
        div.rn.f32 f_invstd, f_one, f_std;
        // Store to s_broadcast
        st.shared.f32 [s_broadcast+0], f_mean;
        st.shared.f32 [s_broadcast+4], f_invstd;
    }
EVAL_BCAST_SYNC:
    bar.sync 0;
    // Load broadcasted mean and invstd
    ld.shared.f32 f_mean,   [s_broadcast+0];
    ld.shared.f32 f_invstd, [s_broadcast+4];
    // Normalize: loop over elements in this channel
    mov.u32 r_idx, r_tid;
EVAL_NORM_LOOP:
    setp.ge.u32 p_loop, r_idx, rM;
    @p_loop bra DONE;
    // Compute element offset: off = (n*C*HW) + (c*HW) + hw
    // n = idx / HW ; hw = idx - n*HW
    div.u32 r_n,  r_idx, rHW;
    mul.lo.u32 r_tmp32, r_n, rHW;
    sub.u32 r_hw, r_idx, r_tmp32;
    // 64-bit math for addresses
    cvt.u64.u32 rd_n64, r_n;
    cvt.u64.u32 rd_C64, rC;
    mul.lo.u64  rd_nC64, rd_n64, rd_C64;     // n*C
    cvt.u64.u32 rd_HW64, rHW;
    mul.lo.u64  rd_nC_HW64, rd_nC64, rd_HW64;    // n*C*HW
    cvt.u64.u32 rd_c64, r_bx;
    mul.lo.u64  rd_c_HW64, rd_c64, rd_HW64;      // c*HW
    cvt.u64.u32 rd_hw64, r_hw;
    add.u64 rd_elem_off, rd_nC_HW64, rd_c_HW64;
    add.u64 rd_elem_off, rd_elem_off, rd_hw64;
    shl.b64 rd_off_bytes, rd_elem_off, 2;
    // Load x, compute y
    {
        .reg .u64 rd_addr;
        add.u64 rd_addr, rd_xg, rd_off_bytes;
        ld.global.f32 f_x, [rd_addr];
    }
    sub.f32 f_tmp1, f_x, f_mean;
    mul.f32 f_tmp1, f_tmp1, f_invstd;
    mul.f32 f_tmp1, f_tmp1, f_w;
    add.f32 f_y,    f_tmp1, f_b;
    {
        .reg .u64 rd_addr;
        add.u64 rd_addr, rd_yg, rd_off_bytes;
        st.global.f32 [rd_addr], f_y;
    }
    // Next idx
    add.u32 r_idx, r_idx, r_ntid;
    bra EVAL_NORM_LOOP;
    // TRAINING path implementation
TRAIN_PATH:
    // Initialize partial sums
    mov.f32 f_sum,   f_zero;
    mov.f32 f_sumsq, f_zero;
    // Loop over elements for partial sums
    mov.u32 r_idx, r_tid;
TRAIN_ACCUM_LOOP:
    setp.ge.u32 p_loop, r_idx, rM;
    @p_loop bra TRAIN_ACCUM_DONE;
    // n = idx / HW ; hw = idx - n*HW
    div.u32 r_n,  r_idx, rHW;
    mul.lo.u32 r_tmp32, r_n, rHW;
    sub.u32 r_hw, r_idx, r_tmp32;
    // 64-bit offset computation
    cvt.u64.u32 rd_n64, r_n;
    cvt.u64.u32 rd_C64, rC;
    mul.lo.u64  rd_nC64, rd_n64, rd_C64;        // n*C
    cvt.u64.u32 rd_HW64, rHW;
    mul.lo.u64  rd_nC_HW64, rd_nC64, rd_HW64;   // n*C*HW
    cvt.u64.u32 rd_c64, r_bx;
    mul.lo.u64  rd_c_HW64, rd_c64, rd_HW64;     // c*HW
    cvt.u64.u32 rd_hw64, r_hw;
    add.u64 rd_elem_off, rd_nC_HW64, rd_c_HW64;
    add.u64 rd_elem_off, rd_elem_off, rd_hw64;
    shl.b64 rd_off_bytes, rd_elem_off, 2;
    // Load x, accumulate
    {
        .reg .u64 rd_addr;
        add.u64 rd_addr, rd_xg, rd_off_bytes;
        ld.global.f32 f_x, [rd_addr];
    }
    add.f32 f_sum, f_sum, f_x;
    mul.f32 f_tmp1, f_x, f_x;
    add.f32 f_sumsq, f_sumsq, f_tmp1;
    // Next idx
    add.u32 r_idx, r_idx, r_ntid;
    bra TRAIN_ACCUM_LOOP;
TRAIN_ACCUM_DONE:
    // Store partials to shared memory
    {
        .reg .u64 rd_saddr;
        // Take base addresses of shared arrays
        mov.u64 rd_s_sum_base,   s_sum;
        mov.u64 rd_s_sumsq_base, s_sumsq;
        // s_sum[tid]
        mul.wide.u32 rd_saddr, r_tid, 4;
        add.u64 rd_saddr, rd_saddr, rd_s_sum_base;
        st.shared.f32 [rd_saddr], f_sum;
        // s_sumsq[tid]
        mul.wide.u32 rd_saddr, r_tid, 4;
        add.u64 rd_saddr, rd_saddr, rd_s_sumsq_base;
        st.shared.f32 [rd_saddr], f_sumsq;
    }
    bar.sync 0;
    // Block reduction
    mov.u32 r_stride, r_ntid;
    shr.u32 r_stride, r_stride, 1; // stride = ntid / 2
REDUCE_LOOP:
    setp.eq.u32 p_red, r_stride, 0;
    @p_red bra REDUCE_DONE;
    setp.lt.u32 p_cond, r_tid, r_stride;
    @!p_cond bra REDUCE_SKIP;
    {
        .reg .u64 rd_a, rd_ba;
        .reg .u32 r_tplus;
        // s_sum[tid] += s_sum[tid + stride]
        mul.wide.u32 rd_a, r_tid, 4;
        add.u64 rd_a, rd_a, rd_s_sum_base;
        add.u32 r_tplus, r_tid, r_stride;
        mul.wide.u32 rd_ba, r_tplus, 4;
        add.u64 rd_ba, rd_ba, rd_s_sum_base;
        ld.shared.f32 f_tmp1, [rd_a];
        ld.shared.f32 f_tmp2, [rd_ba];
        add.f32 f_tmp1, f_tmp1, f_tmp2;
        st.shared.f32 [rd_a], f_tmp1;
        // s_sumsq reduction
        mul.wide.u32 rd_a, r_tid, 4;
        add.u64 rd_a, rd_a, rd_s_sumsq_base;
        mul.wide.u32 rd_ba, r_tplus, 4;
        add.u64 rd_ba, rd_ba, rd_s_sumsq_base;
        ld.shared.f32 f_tmp1, [rd_a];
        ld.shared.f32 f_tmp2, [rd_ba];
        add.f32 f_tmp1, f_tmp1, f_tmp2;
        st.shared.f32 [rd_a], f_tmp1;
    }
REDUCE_SKIP:
    bar.sync 0;
    shr.u32 r_stride, r_stride, 1;
    bra REDUCE_LOOP;
REDUCE_DONE:
    // Thread 0 computes mean/var, updates running stats, broadcasts
    setp.eq.u32 p_is_t0, r_tid, 0;
    @!p_is_t0 bra TRAIN_BCAST_SYNC;
    // Load totals
    ld.shared.f32 f_sum,   [s_sum+0];
    ld.shared.f32 f_sumsq, [s_sumsq+0];
    // f_M = float(M)
    cvt.rn.f32.u32 f_M, rM;
    // mean = sum / M
    div.rn.f32 f_mean, f_sum, f_M;
    // e2 = sumsq / M
    div.rn.f32 f_e2, f_sumsq, f_M;
    // var = e2 - mean*mean
    mul.f32 f_tmp1, f_mean, f_mean;
    sub.f32 f_var, f_e2, f_tmp1;
    // inv_std = 1 / sqrt(var + eps)
    add.f32 f_tmp1, f_var, f_eps;
    sqrt.rn.f32 f_std, f_tmp1;
    div.rn.f32 f_invstd, f_one, f_std;
    // Broadcast mean and inv_std
    st.shared.f32 [s_broadcast+0], f_mean;
    st.shared.f32 [s_broadcast+4], f_invstd;
    // Update running stats: rm = (1-m)*rm + m*mean ; rv = (1-m)*rv + m*var
    sub.f32 f_omn, f_one, f_momentum;
    {
        .reg .u64 rd_tmp;
        add.u64 rd_tmp, rd_rmg, rd_c4;
        ld.global.f32 f_rm_old, [rd_tmp];
        // new mean
        mul.f32 f_tmp1, f_rm_old, f_omn;
        mul.f32 f_tmp2, f_mean,   f_momentum;
        add.f32 f_rm_new, f_tmp1, f_tmp2;
        st.global.f32 [rd_tmp], f_rm_new;
        add.u64 rd_tmp, rd_rvg, rd_c4;
        ld.global.f32 f_rv_old, [rd_tmp];
        // new var
        mul.f32 f_tmp1, f_rv_old, f_omn;
        mul.f32 f_tmp2, f_var,    f_momentum;
        add.f32 f_rv_new, f_tmp1, f_tmp2;
        st.global.f32 [rd_tmp], f_rv_new;
    }
    // Increment num_batches_tracked once per kernel (block 0, thread 0)
    setp.eq.u32 p_is_b0, r_bx, 0;
    @!p_is_b0 bra TRAIN_BCAST_SYNC;
    {
        .reg .u64 rd_val64;
        ld.global.u64 rd_val64, [rd_nbtg];
        add.u64 rd_val64, rd_val64, 1;
        st.global.u64 [rd_nbtg], rd_val64;
    }
TRAIN_BCAST_SYNC:
    bar.sync 0;
    // Load broadcasted mean and invstd
    ld.shared.f32 f_mean,   [s_broadcast+0];
    ld.shared.f32 f_invstd, [s_broadcast+4];
    // Normalize: loop over elements in this channel
    mov.u32 r_idx, r_tid;
TRAIN_NORM_LOOP:
    setp.ge.u32 p_loop, r_idx, rM;
    @p_loop bra DONE;
    // n = idx / HW ; hw = idx - n*HW
    div.u32 r_n,  r_idx, rHW;
    mul.lo.u32 r_tmp32, r_n, rHW;
    sub.u32 r_hw, r_idx, r_tmp32;
    // 64-bit offset computation
    cvt.u64.u32 rd_n64, r_n;
    cvt.u64.u32 rd_C64, rC;
    mul.lo.u64  rd_nC64, rd_n64, rd_C64;        // n*C
    cvt.u64.u32 rd_HW64, rHW;
    mul.lo.u64  rd_nC_HW64, rd_nC64, rd_HW64;   // n*C*HW
    cvt.u64.u32 rd_c64, r_bx;
    mul.lo.u64  rd_c_HW64, rd_c64, rd_HW64;     // c*HW
    cvt.u64.u32 rd_hw64, r_hw;
    add.u64 rd_elem_off, rd_nC_HW64, rd_c_HW64;
    add.u64 rd_elem_off, rd_elem_off, rd_hw64;
    shl.b64 rd_off_bytes, rd_elem_off, 2;
    // Load x, compute y
    {
        .reg .u64 rd_addr;
        add.u64 rd_addr, rd_xg, rd_off_bytes;
        ld.global.f32 f_x, [rd_addr];
    }
    sub.f32 f_tmp1, f_x, f_mean;
    mul.f32 f_tmp1, f_tmp1, f_invstd;
    mul.f32 f_tmp1, f_tmp1, f_w;
    add.f32 f_y,    f_tmp1, f_b;
    {
        .reg .u64 rd_addr;
        add.u64 rd_addr, rd_yg, rd_off_bytes;
        st.global.f32 [rd_addr], f_y;
    }
    // Next idx
    add.u32 r_idx, r_idx, r_ntid;
    bra TRAIN_NORM_LOOP;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("bn2d_fwd")

class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        # Match reference BatchNorm2d defaults (affine=True, track_running_stats=True)
        self.num_features = num_features
        self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(num_features, dtype=torch.float32))
        # Running stats
        self.register_buffer("running_mean", torch.zeros(num_features, dtype=torch.float32))
        self.register_buffer("running_var", torch.ones(num_features, dtype=torch.float32))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.int64))
        self.momentum = 0.1
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensor input.")
        if x.dtype != torch.float32:
            raise RuntimeError("ModelNew only supports float32 inputs.")
        if x.dim() != 4 or x.size(1) != self.num_features:
            raise RuntimeError("Input must be NCHW with C == num_features.")

        N, C, H, W = x.shape
        y = torch.empty_like(x)

        module = _get_ptx_module()
        module.launch(
            "bn2d_fwd",
            grid=(C, 1, 1),
            block=(256, 1, 1),
            arguments=[
                x, y,
                self.weight, self.bias,
                self.running_mean, self.running_var,
                self.num_batches_tracked,
                i32(N), i32(C), i32(H), i32(W),
                i32(1 if self.training else 0),
                f32(float(self.momentum)),
                f32(float(self.eps)),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

