    .shared .align 4 .f32 s_sum[256];
    .shared .align 4 .f32 s_sumsq[256];
    .shared .align 4 .f32 s_broadcast[2]; // [0]: mean, [1]: inv_std

    // Registers
    .reg .pred p_train, p_cond, p_loop, p_red, p_is_t0, p_is_b0, p_oob_c;
    .reg .u32 rN, rC, rH, rW, rHW, rM;
    .reg .u32 r_tid, r_ntid, r_bx;
    .reg .u32 r_idx, r_stride, r_n, r_hw, r_tmp32;
    .reg .u32 r_training;
    .reg .u64 rd_x, rd_y, rd_w, rd_b, rd_rm, rd_rv, rd_nbt;
    .reg .u64 rd_xg, rd_yg, rd_wg, rd_bg, rd_rmg, rd_rvg, rd_nbtg;
     .reg .u64 rd_off_bytes, rd_elem_off, rd_tmp64, rd_c4, rd_c64, rd_M64, rd_HW64, rd_C64, rd_n64, rd_nC64, rd_nC_HW64, rd_c_HW64, rd_hw64, rd_s_sum_base, rd_s_sumsq_base;
    .reg .f32 f_momentum, f_eps, f_sum, f_sumsq, f_one, f_zero;
    .reg .f32 f_mean, f_var, f_e2, f_std, f_invstd, f_M, f_x, f_y, f_w, f_b;
    .reg .f32 f_tmp1, f_tmp2, f_omn; // one_minus_m
    .reg .f32 f_rm_old, f_rv_old, f_rm_new, f_rv_new;

    // Load params
    ld.param.u64 rd_x,   [x_ptr];
    ld.param.u64 rd_y,   [y_ptr];
    ld.param.u64 rd_w,   [w_ptr];
    ld.param.u64 rd_b,   [b_ptr];
    ld.param.u64 rd_rm,  [rm_ptr];
    ld.param.u64 rd_rv,  [rv_ptr];
    ld.param.u64 rd_nbt, [nbt_ptr];
    ld.param.u32 rN,     [N];
    ld.param.u32 rC,     [C];
    ld.param.u32 rH,     [H];
    ld.param.u32 rW,     [W];
    ld.param.u32 r_training, [training];
    ld.param.f32 f_momentum, [momentum];
    ld.param.f32 f_eps, [eps];

    // Convert to global addresses
    cvta.to.global.u64 rd_xg,   rd_x;
    cvta.to.global.u64 rd_yg,   rd_y;
    cvta.to.global.u64 rd_wg,   rd_w;
    cvta.to.global.u64 rd_bg,   rd_b;
    cvta.to.global.u64 rd_rmg,  rd_rm;
    cvta.to.global.u64 rd_rvg,  rd_rv;
    cvta.to.global.u64 rd_nbtg, rd_nbt;

    // Thread/block indices
    mov.u32 r_tid, %tid.x;
    mov.u32 r_ntid, %ntid.x;
    mov.u32 r_bx, %ctaid.x;

    // Bounds check for channel
    setp.ge.u32 p_oob_c, r_bx, rC;
    @p_oob_c ret;

