        add.u64 rd_tmp, rd_rvg, rd_c4;
        ld.global.f32 f_var, [rd_tmp];
        add.f32 f_var, f_var, f_eps;
        sqrt.rn.f32 f_std, f_var;
        div.rn.f32 f_invstd, f_one, f_std;
