        st.shared.f32 [s_broadcast+0], f_mean;
        st.shared.f32 [s_broadcast+4], f_invstd;
    }
EVAL_BCAST_SYNC:
    bar.sync 0;
    // Load broadcasted mean and invstd
    ld.shared.f32 f_mean,   [s_broadcast+0];
    ld.shared.f32 f_invstd, [s_broadcast+4];

    // Normalize: loop over elements in this channel
    mov.u32 r_idx, r_tid;
EVAL_NORM_LOOP:
    setp.ge.u32 p_loop, r_idx, rM;
    @p_loop bra DONE;

    // Compute element offset: off = (n*C*HW) + (c*HW) + hw
    // n = idx / HW ; hw = idx - n*HW
    div.u32 r_n,  r_idx, rHW;
    mul.lo.u32 r_tmp32, r_n, rHW;
    sub.u32 r_hw, r_idx, r_tmp32;

    // 64-bit math for addresses
    cvt.u64.u32 rd_n64, r_n;
    cvt.u64.u32 rd_C64, rC;
    mul.lo.u64  rd_nC64, rd_n64, rd_C64;     // n*C
    cvt.u64.u32 rd_HW64, rHW;
    mul.lo.u64  rd_nC_HW64, rd_nC64, rd_HW64;    // n*C*HW

    cvt.u64.u32 rd_c64, r_bx;
    mul.lo.u64  rd_c_HW64, rd_c64, rd_HW64;      // c*HW

    cvt.u64.u32 rd_hw64, r_hw;

    add.u64 rd_elem_off, rd_nC_HW64, rd_c_HW64;
    add.u64 rd_elem_off, rd_elem_off, rd_hw64;

    shl.b64 rd_off_bytes, rd_elem_off, 2;

    // Load x, compute y
    {
        .reg .u64 rd_addr;
        add.u64 rd_addr, rd_xg, rd_off_bytes;
        ld.global.f32 f_x, [rd_addr];
    }
    sub.f32 f_tmp1, f_x, f_mean;
    mul.f32 f_tmp1, f_tmp1, f_invstd;
    mul.f32 f_tmp1, f_tmp1, f_w;
    add.f32 f_y,    f_tmp1, f_b;

    {
        .reg .u64 rd_addr;
        add.u64 rd_addr, rd_yg, rd_off_bytes;
        st.global.f32 [rd_addr], f_y;
    }

    // Next idx
    add.u32 r_idx, r_idx, r_ntid;
    bra EVAL_NORM_LOOP;

    // TRAINING path implementation
TRAIN_PATH:
    // Initialize partial sums
    mov.f32 f_sum,   f_zero;
    mov.f32 f_sumsq, f_zero;

    // Loop over elements for partial sums
    mov.u32 r_idx, r_tid;
TRAIN_ACCUM_LOOP:
    setp.ge.u32 p_loop, r_idx, rM;
    @p_loop bra TRAIN_ACCUM_DONE;

    // n = idx / HW ; hw = idx - n*HW
    div.u32 r_n,  r_idx, rHW;
    mul.lo.u32 r_tmp32, r_n, rHW;
    sub.u32 r_hw, r_idx, r_tmp32;

    // 64-bit offset computation
    cvt.u64.u32 rd_n64, r_n;
    cvt.u64.u32 rd_C64, rC;
    mul.lo.u64  rd_nC64, rd_n64, rd_C64;        // n*C
    cvt.u64.u32 rd_HW64, rHW;
    mul.lo.u64  rd_nC_HW64, rd_nC64, rd_HW64;   // n*C*HW

    cvt.u64.u32 rd_c64, r_bx;
    mul.lo.u64  rd_c_HW64, rd_c64, rd_HW64;     // c*HW

    cvt.u64.u32 rd_hw64, r_hw;

    add.u64 rd_elem_off, rd_nC_HW64, rd_c_HW64;
    add.u64 rd_elem_off, rd_elem_off, rd_hw64;

    shl.b64 rd_off_bytes, rd_elem_off, 2;

    // Load x, accumulate
    {
        .reg .u64 rd_addr;
        add.u64 rd_addr, rd_xg, rd_off_bytes;
        ld.global.f32 f_x, [rd_addr];
    }
    add.f32 f_sum, f_sum, f_x;
    mul.f32 f_tmp1, f_x, f_x;
    add.f32 f_sumsq, f_sumsq, f_tmp1;

    // Next idx
    add.u32 r_idx, r_idx, r_ntid;
    bra TRAIN_ACCUM_LOOP;

TRAIN_ACCUM_DONE:
